package org.apache.commons.lang.time;

import junit.framework.TestCase;

public class AgentBRT_Lang_55_raw_diff_Test extends TestCase {

    public void testReproduceBug() throws Exception {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();
        long suspendedTime = stopWatch.getTime();
        Thread.sleep(10); // Ensure some time passes
        stopWatch.stop();
        // The bug is that getTime() should not change when stopwatch is suspended
        assertEquals("Time should not change when stopwatch is suspended", suspendedTime, stopWatch.getTime());
    }
}

